            url = urlsplit(href)
            if url.scheme or url.netloc:
                errors.append('외부 자원/링크: ' + href)
                continue
            if not url.path:
                if url.fragment and unquote(url.fragment) not in ids:
                    errors.append('링크 앵커 없음: ' + href)
                continue
